# nothing importable, install the pinned set into deps/ on first boot.
# Packages are pinned inline — no requirements.txt sidecar needed, so a
# lone app.py heals itself anywhere pip + network exist.
_HEAL_DEPS = ["flask>=2.3", "psycopg2-binary>=2.9", "pyjwt>=2.8", "flask-compress>=1.14"]

