def _load_settings_file():
    """Hosts without an env-var UI (KataBump/Pterodactyl lite) can drop a
    settings.env next to app.py with KEY=VALUE lines. Values here override
    anything the host pre-injected — the file is the operator's explicit
    config for this machine."""
    _path = os.path.join(BASE_DIR, "settings.env")
    if not os.path.exists(_path):
        return
    _loaded = []
    try:
        with open(_path, "r", encoding="utf-8") as f:
            for _line in f:
                _line = _line.strip()
                if not _line or _line.startswith("#") or "=" not in _line:
                    continue
                _k, _v = _line.split("=", 1)
                _k = _k.strip()
                _v = _v.strip().strip('"').strip("'")
                if _k:
                    os.environ[_k] = _v
                    _loaded.append(_k)
        print("[PANEL] settings.env loaded: %s" % (", ".join(_loaded) or "(no keys)"), flush=True)
    except Exception as _sf_exc:
        print("[PANEL] settings.env failed: %r" % (_sf_exc,), flush=True)


_load_settings_file()

