def _is_proxy_ip(ip: str) -> bool:
    """Block VPN/proxy/Tor sources at registration. Fail-open: if the
    intelligence API is unreachable, allow — never lock out real users."""
    if not ip:
        return False
    try:
        import urllib.request as _ur
        import json as _json
        _req = _ur.Request(f"https://ipwho.is/{ip}",
                           headers={"User-Agent": "velum-panel/1.0"})
        with _ur.urlopen(_req, timeout=4) as _r:
            _d = _json.loads(_r.read().decode("utf-8", "replace"))
        if not isinstance(_d, dict) or not _d.get("success"):
            return False
        _conn = _d.get("connection") or {}
        _sec = _d.get("security") or {}
        return bool(_conn.get("is_proxy") or _sec.get("is_proxy")
                    or _sec.get("is_vpn") or _sec.get("is_tor"))
    except Exception:
        return False


