def _settings_get(k: str) -> str:
    rows = _q("SELECT v FROM settings WHERE k = ?", (k,), fetch=True)
    return str(rows[0]["v"]) if rows else ""


def _settings_set(k: str, v: str):
    # Portable upsert (SQLite + Postgres)
    _q("INSERT INTO settings (k, v) SELECT ?, ? WHERE NOT EXISTS "
       "(SELECT 1 FROM settings WHERE k = ?)", (k, v, k))
    _q("UPDATE settings SET v = ? WHERE k = ?", (v, k))


# ── Subscription engine ──────────────────────────────────────

_SUB_TIERS = {
    "trial":    {"name": "TRIAL",    "cents": 0,    "days": 3,  "prefix": "0T3"},
    "basic":    {"name": "BASIC",    "cents": 500,  "days": 30, "prefix": "0X1"},
    "pro":      {"name": "PRO",      "cents": 1500, "days": 30, "prefix": "1X2"},
    "lifetime": {"name": "LIFETIME", "cents": 7500, "days": None, "prefix": "2X3"},
}


def _sub_tiers() -> dict:
    return {k: dict(v) for k, v in _SUB_TIERS.items()}


def _sub_coin_addresses() -> dict:
    return {
        "BTC": _settings_get("pay_BTC"),
        "LTC": _settings_get("pay_LTC"),
        "ETH": _settings_get("pay_ETH"),
        "SOL": _settings_get("pay_SOL"),
    }


def _sub_coin_amounts(tier: str) -> dict:
    """Fixed per-tier crypto amounts (set by admin). Keys: pay_{tier}_{coin}."""
    out = {}
    for coin in ("BTC", "LTC", "ETH", "SOL"):
        out[coin] = _settings_get(f"pay_{tier}_{coin}")
    return out


def _gen_license_key(tier: str) -> str:
    import secrets
    _alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    _prefix = _sub_tiers().get(tier, {}).get("prefix", "0X1")
    _body = "-".join("".join(secrets.choice(_alphabet) for _ in range(4)) for _ in range(3))
    return f"{_prefix}-{_body}"


def _license_expiry(tier: str) -> str:
    _days = _sub_tiers().get(tier, {}).get("days")
    if not _days:
        return ""
    return (datetime.now(timezone.utc) + timedelta(days=_days)).isoformat(timespec="seconds")


def _license_mint(tier: str, owner: str, coin: str = "", tx: str = "") -> str:
    """Create a license row. Returns the plaintext key (shown once)."""
    key = _gen_license_key(tier)
    _q("INSERT INTO licenses (key, key_hash, tier, expires_at, created_at, "
       "activated_at, owner, status, payment_coin, payment_tx) "
       "VALUES (?,?,?,?,?,NULL,?,?,?,?)",
       (key, hashlib.sha256(key.encode()).hexdigest(), tier,
        _license_expiry(tier) or None, _now(), owner, "active", coin, tx))
    return key


def _license_state(uname: str) -> dict:
    """Best license for a user: lifetime > unexpired > latest."""
    rows = _q("SELECT * FROM licenses WHERE owner = ? AND status = 'active' "
              "ORDER BY (expires_at IS NULL) DESC, expires_at DESC", (uname,), fetch=True) or []
    rows = [dict(r) for r in rows]
    now = datetime.now(timezone.utc)
    out = {"has": False, "tier": "", "key": "", "days_left": 0, "expires_at": "", "lifetime": False}
    for r in rows:
        exp = r.get("expires_at") or ""
        if not exp:
            out.update({"has": True, "tier": r["tier"], "key": r["key"],
                        "lifetime": True, "expires_at": ""})
            break
        try:
            exp_dt = datetime.fromisoformat(exp)
        except Exception:
            continue
        if exp_dt > now:
            out.update({"has": True, "tier": r["tier"], "key": r["key"],
                        "expires_at": exp, "lifetime": False,
                        "days_left": max(0, round((exp_dt - now).total_seconds() / 86400, 2))})
            break
    return out


def _device_lock_active(tier: str) -> bool:
    """One key = one device. Disable globally with setting license_device_lock=0,
    or restrict which tiers are locked via device_lock_tiers (comma list)."""
    if _settings_get("license_device_lock") == "0":
        return False
    _tiers = (_settings_get("device_lock_tiers") or "trial,basic,pro,lifetime").lower()
    return str(tier or "").lower() in [t.strip() for t in _tiers.split(",") if t.strip()]


def _license_verify(key: str, device_id: str = "", device_label: str = "") -> dict:
    """Public verification (used by the builder). Returns ok/tier/expiry.
    Device binding: the first device that presents a key claims it; any other
    device is refused until an admin resets the binding."""
    key = (key or "").strip().upper()
    device_id = (device_id or "").strip()[:64]
    device_label = (device_label or "").strip()[:120]
    if not key:
        return {"ok": False, "error": "no key"}
    rows = _q("SELECT * FROM licenses WHERE key = ?", (key,), fetch=True) or []
    if not rows:
        return {"ok": False, "error": "unknown key"}
    r = dict(rows[0])
    if r.get("status") != "active":
        return {"ok": False, "error": "revoked"}
    exp = r.get("expires_at") or ""
    if exp:
        try:
            if datetime.fromisoformat(exp) <= datetime.now(timezone.utc):
                return {"ok": False, "error": "expired"}
        except Exception:
            pass
    # ── device binding: first device wins ──
    _bound = (r.get("device_id") or "").strip()
    _lock = _device_lock_active(r.get("tier", ""))
    _activated = False
    if _lock and device_id:
        if not _bound:
            _q("UPDATE licenses SET device_id = ?, device_label = ?, "
               "activated_at = COALESCE(activated_at, ?) WHERE key = ?",
               (device_id, device_label, _now(), key))
            _bound = device_id
            _activated = True
        elif _bound != device_id:
            return {"ok": False, "error": "KEY ACTIVATED ON ANOTHER DEVICE",
                    "device_locked": True, "tier": r["tier"]}, 403
    elif _lock and _bound:
        # bound key presented without a device id — refuse rather than leak
        return {"ok": False, "error": "KEY ACTIVATED ON ANOTHER DEVICE",
                "device_locked": True, "tier": r["tier"]}, 403
    _tier = _sub_tiers().get(r["tier"], {})
    _days_left = None
    if exp:
        try:
            _days_left = max(0.0, round(
                (datetime.fromisoformat(exp) - datetime.now(timezone.utc)).total_seconds() / 86400, 2))
        except Exception:
            _days_left = None
    if r["tier"] == "basic":
        _wm = "VELUM-BASIC " + key[:13]
    elif r["tier"] == "trial":
        _wm = "VELUM-TRIAL " + key[:13]
    else:
        _wm = ""
    return {
        "ok": True,
        "tier": r["tier"],
        "tier_name": _tier.get("name", r["tier"]),
        "expires_at": exp,
        "days_left": _days_left,
        "lifetime": not exp,
        "watermark": _wm,
        "activated": _activated,
        "device_bound": bool(_bound),
    }


def _ensure_admin_token():
    """Resolve the auth key from the database; generate + persist on first run.
    Env var (if set) wins and marks the panel as claimed."""
    global ADMIN_TOKEN
    if ADMIN_TOKEN:
        # Explicit operator key â€” panel starts claimed, nothing is revealed.
        _settings_set("auth_claimed", "1")
        return
    ADMIN_TOKEN = _settings_get("admin_token")
    if ADMIN_TOKEN:
        return
    ADMIN_TOKEN = "vl_" + uuid.uuid4().hex
    _settings_set("admin_token", ADMIN_TOKEN)
    ADMIN_TOKEN = _settings_get("admin_token")  # re-read: last-write-wins under races
    _settings_set("auth_claimed", "0")
    print(f"[PANEL] Generated auth key -> stored in database (shown once on the login page)", flush=True)
    print(f"[PANEL] AUTH KEY (username: {ADMIN_USER}): {ADMIN_TOKEN}", flush=True)


def _ensure_jwt_secret():
    """JWT signing secret: env override, else DB-persisted, else generated.
    Same zero-config model as the auth key â€” survives Vercel cold starts."""
    global JWT_SECRET
    if JWT_SECRET:
        return
    JWT_SECRET = _settings_get("jwt_secret")
    if JWT_SECRET:
        return
    JWT_SECRET = uuid.uuid4().hex + uuid.uuid4().hex
    _settings_set("jwt_secret", JWT_SECRET)
    JWT_SECRET = _settings_get("jwt_secret")  # re-read under race
    print("[PANEL] Generated JWT secret -> stored in database", flush=True)


# ── Lazy boot ──────────────────────────────────────────────
# DB init runs on the FIRST REQUEST, not at import time. On Vercel an
# import-time crash takes down every route with a useless 500 â€” lazy boot
# turns a misconfigured DATABASE_URL into a clear 503 with instructions
# while the static site keeps serving.

_BOOT_LOCK = threading.Lock()
_DB_READY = False
_DB_ERROR = ""


def _boot():
    """Initialize DB + auth material once per process. Returns "" on success
    or a human-readable error string. Retried on every request until it
    succeeds (e.g. after the operator fixes DATABASE_URL and redeploys)."""
    global _DB_READY, _DB_ERROR
    if _DB_READY:
        return ""
    with _BOOT_LOCK:
        if _DB_READY:
            return ""
        try:
            _init_db()
            _ensure_admin_token()
            _ensure_jwt_secret()
            _DB_READY = True
            _DB_ERROR = ""
        except Exception as e:
            _DB_READY = False
            if not _PG and os.environ.get("VERCEL"):
                _DB_ERROR = ("Database not configured â€” add a Postgres DSN to DATABASE_URL "
                             "in Vercel Project Settings > Environment Variables, then redeploy.")
            else:
                _DB_ERROR = str(e)
            print(f"[PANEL] Boot failed: {_DB_ERROR}", flush=True)
        return _DB_ERROR


@app.before_request
def _boot_gate():
    if request.path == "/api/health":
        return None
    err = _boot()
    if request.path.startswith("/api/"):
        if err:
            return jsonify({"error": "We couldn't reach the database. Try again in a moment.", "detail": err}), 503
        if request.path.startswith("/api/bot/"):
            return None  # bot heartbeats are key-auth'd — unrelated to panel-user IPs
        if _ip_is_banned(_client_ip()):
            return jsonify({"error": "this address has been blocked"}), 403
        return None
    # Site paths: serve the block wall instead of the login page.
    if _ip_is_banned(_client_ip()):
        return (
            '<!DOCTYPE html><html><head><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width,initial-scale=1">'
            '<title>Blocked — VELUM</title></head>'
            '<body style="margin:0;background:#060A12;color:#D9E6F2;font-family:Segoe UI,system-ui,sans-serif;'
            'display:flex;align-items:center;justify-content:center;height:100vh">'
            '<div style="background:#0A121C;border:1px solid #E0716A;border-radius:14px;padding:44px 56px;text-align:center">'
            '<div style="font-size:19px;letter-spacing:.5px;color:#F2C9CD;font-weight:650">'
            'We can\'t let this address in right now</div>'
            '<div style="color:#7D92A8;font-size:13px;margin-top:12px">'
            'This IP has been blocked.</div>'
            '</div></body></html>', 403)
    return None


@app.get("/api/health")
def health():
    """Deployment self-check â€” no DB secrets, just the facts. Tells you
    exactly why the panel can't boot: missing DATABASE_URL or a bad one."""
    err = _boot()
    return jsonify({
        "ok": not err,
        "db_configured": bool(DB_URL),
        "detail": err or "",
    }), (200 if not err else 503)

# ── CORS (the builder GUI generates keys straight from the panel) ──

@app.after_request
def _cors(resp):
    resp.headers["Access-Control-Allow-Origin"] = "*"
    resp.headers["Access-Control-Allow-Headers"] = "Content-Type, X-Admin-Token, X-Bot-Key, Authorization, If-None-Match"
    resp.headers["Access-Control-Allow-Methods"] = "GET, POST, DELETE, OPTIONS"
    resp.headers["Access-Control-Expose-Headers"] = "ETag"
    return resp

# ── Auth ──

def _auth():
    """Resolve the caller: ("admin", name) or ("user", name), or (None, None).

    1. PANEL_NO_AUTH=1 (local mode) â€” everything is admin, zero friction.
    2. Authorization: Bearer <JWT>  â€” verified locally, zero DB traffic.
       This is the fast path every logged-in request takes.
    3. X-Admin-Token == master key â€” used by the builder GUI's GENERATE KEY.
    4. Legacy DB session tokens (pre-JWT) â€” still honored.
    """
    if NO_AUTH:
        return ("admin", ADMIN_USER)
    authz = request.headers.get("Authorization", "")
    if authz.startswith("Bearer "):
        payload = _verify_jwt(authz[7:])
        if payload:
            g.auth_payload = payload
            return (str(payload.get("role")), str(payload.get("sub")))
        return (None, None)  # bad/expired token â€” do NOT fall through
    t = request.headers.get("X-Admin-Token", "")
    if t and t == ADMIN_TOKEN:
        return ("admin", ADMIN_USER)
    if t:
        rows = _q("SELECT username FROM sessions WHERE token = ?", (t,), fetch=True)
        if rows:
            return ("user", rows[0]["username"])
    return (None, None)


def _user_api_key(uname: str) -> str:
    rows = _q("SELECT api_key FROM users WHERE username = ?", (uname,), fetch=True)
    return str(rows[0]["api_key"]) if rows else ""


def _user_key_active(uname: str) -> bool:
    uk = _user_api_key(uname)
    if not uk:
        return False
    rows = _q("SELECT active FROM api_keys WHERE key = ?", (uk,), fetch=True)
    return bool(rows and rows[0]["active"])


def _jwt_stale() -> bool:
    """Write-path check: JWT `v` claim vs the user's auth_version row.
    Bumping auth_version (password change / ban) instantly kills the token
    for write operations without a per-request DB hit on read paths."""
    payload = getattr(g, "auth_payload", None)
    if not payload or payload.get("role") != "user":
        return False
    rows = _q("SELECT auth_version FROM users WHERE username = ?", (payload["sub"],), fetch=True)
    return (not rows) or (int(rows[0]["auth_version"] or 0) != int(payload.get("v") or 0))


def _user_bot_ids(uname: str):
    uk = _user_api_key(uname)
    return [r["id"] for r in (_q("SELECT id FROM bots WHERE key = ?", (uk,), fetch=True) or [])]


@app.get("/api/panel/setup")
def panel_setup():
    """First-run bootstrap: until the panel is claimed, reveal the generated
    auth key ONCE on the login page. After the first successful login the
    key is never exposed again."""
    claimed = _settings_get("auth_claimed") == "1"
    if NO_AUTH:
        return jsonify({"configured": True, "auth_disabled": True, "username": ADMIN_USER})
    if not claimed:
        return jsonify({"configured": False, "username": ADMIN_USER, "auth_key": ADMIN_TOKEN})
    return jsonify({"configured": True})


@app.post("/api/panel/register")
def panel_register():
    """Create an account + issue its builder auth key (X-Bot-Key) + a JWT.
    Hardened against account farming: max 3 attempts/hour per IP,
    proxy/VPN/Tor sources refused, ONE account per IP."""
    d = request.get_json(force=True, silent=True) or {}
    u = str(d.get("username") or "").strip()
    p = str(d.get("password") or "")
    if not re.fullmatch(r"[A-Za-z0-9_.\-]{3,32}", u):
        return jsonify({"error": "username: 3-32 chars (a-z, 0-9, . _ -)"}), 400
    if len(p) < 6:
        return jsonify({"error": "password: at least 6 characters"}), 400
    if u.lower() == ADMIN_USER.lower():
        return jsonify({"error": "username taken"}), 409
    if _q("SELECT 1 FROM users WHERE username = ?", (u,), fetch=True):
        return jsonify({"error": "username taken"}), 409
    # honeypot — bots fill every field; humans never see this one
    if str(d.get("website") or "").strip():
        return jsonify({"error": "Sign-ups aren't available from this network."}), 403
    # kill switch — closed until the admin opens sign-ups
    _reg_open = _settings_get("register_open") == "1"
    if not _reg_open:
        return jsonify({"error": "Sign-ups are closed right now."}), 403
    _ip = _client_ip()
    # anti-DDoS: max 3 registration attempts per hour per IP
    _cut = (datetime.now(timezone.utc) - timedelta(hours=1)).isoformat(timespec="seconds")
    _q("DELETE FROM register_attempts WHERE ts < ?", (_cut,))
    _cnt = _q("SELECT COUNT(*) AS c FROM register_attempts WHERE ip = ?", (_ip,), fetch=True)
    if _cnt and int(_cnt[0]["c"]) >= 3:
        return jsonify({"error": "Too many tries from this address — give it an hour."}), 429
    _q("INSERT INTO register_attempts (ip, ts) VALUES (?,?)", (_ip, _now()))
    # proxy wall — VPNs/datacenter relays can't make accounts at all
    if _is_proxy_ip(_ip):
        return jsonify({"error": "Sign-ups aren't available from this network."}), 403
    # one account per IP — no farming behind NATs or rotating proxies
    if _q("SELECT 1 FROM users WHERE reg_ip = ?", (_ip,), fetch=True):
        return jsonify({"error": "This address already has an account."}), 409
    key = "rk_" + uuid.uuid4().hex
    salt = uuid.uuid4().hex
    pw_hash = hashlib.pbkdf2_hmac("sha256", p.encode(), salt.encode(), 120000).hex()
    _q("INSERT INTO users (username, password, api_key, created, auth_version, balance, last_login, last_ip, reg_ip) "
       "VALUES (?,?,?,?,0,0,?,?,?)",
       (u, pw_hash + "$" + salt, key, _now(), _now(), _ip, _ip))
    _q("INSERT INTO api_keys (key, label, created, active) VALUES (?,?,?,1)",
       (key, u, _now()))
    jwt_bundle = _issue_jwt(u, "user", 0)
    return jsonify({"ok": True, "username": u, "role": "user",
                    "api_key": key, **jwt_bundle})


@app.post("/api/panel/login")
def panel_login():
    """Login: admin (username + master auth key) or registered user.
    Returns a JWT â€” subsequent requests are verified locally, no DB auth."""
    d = request.get_json(force=True, silent=True) or {}
    u = str(d.get("username") or "").strip()
    p = str(d.get("password") or "").strip()
    cutoff = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat(timespec="seconds")
    _q("DELETE FROM sessions WHERE created < ?", (cutoff,))
    if u == ADMIN_USER and p == ADMIN_TOKEN:
        _settings_set("auth_claimed", "1")
        return jsonify({"ok": True, "username": ADMIN_USER, "role": "admin",
                        **_issue_jwt(ADMIN_USER, "admin", 0)})
    rows = _q("SELECT username, password, api_key, auth_version FROM users WHERE username = ?",
              (u,), fetch=True)
    if rows and "$" in rows[0]["password"]:
        h, salt = rows[0]["password"].split("$", 1)
        if hashlib.pbkdf2_hmac("sha256", p.encode(), salt.encode(), 120000).hex() == h:
            if not _user_key_active(u):
                return jsonify({"error": "This account has been suspended."}), 403
            ver = int(rows[0]["auth_version"] or 0)
            _q("UPDATE users SET last_login = ?, last_ip = ? WHERE username = ?",
               (_now(), _client_ip(), u))
            return jsonify({"ok": True, "username": u, "role": "user",
                            "api_key": rows[0]["api_key"],
                            **_issue_jwt(u, "user", ver)})
    return jsonify({"error": "That username and password don't match."}), 403


def _key_ok(key: str) -> bool:
    if not key:
        return False
    rows = _q("SELECT active FROM api_keys WHERE key = ?", (key,), fetch=True)
    return bool(rows and rows[0]["active"])


