def _tick_key() -> str:
    _k = _settings_get("tick_key")
    if not _k:
        import secrets
        _k = secrets.token_hex(12)
        _settings_set("tick_key", _k)
    return _k


def _fetch_coin_txs(coin: str, addr: str):
    """Pull recent incoming txs for an address. Primary explorer + fallback.
    Returns [{txid, amount, time}] in coin units (confirmed only)."""
    import urllib.request as _ur
    import json as _json
    out = []
    if coin in ("BTC", "LTC"):
        # 1. blockstream family (confirmed txs only)
        for base in (["https://blockstream.info/api", "https://mempool.space/api"]
                     if coin == "BTC" else
                     ["https://litecoinspace.org/api", "https://blockstream.info/liquid/api"]):
            try:
                with _ur.urlopen(f"{base}/address/{addr}/txs", timeout=15) as r:
                    txs = _json.loads(r.read().decode())
                for t in txs:
                    ts = ""
                    if t.get("status", {}).get("confirmed"):
                        ts = str(t["status"].get("block_time") or "")
                    amt = 0.0
                    for vo in t.get("vout", []):
                        if addr == (vo.get("scriptpubkey_address") or ""):
                            amt += float(vo.get("value") or 0)
                    if amt > 0:
                        out.append({"txid": t.get("txid", ""), "amount": amt, "time": ts})
                if out:
                    break
            except Exception:
                continue
        # 2. sochain fallback
        if not out:
            try:
                net = "BTC" if coin == "BTC" else "LTC"
                with _ur.urlopen(f"https://sochain.com/api/v2/get_tx_received/{net}/{addr}", timeout=15) as r:
                    d = _json.loads(r.read().decode())
                for t in (d.get("data", {}).get("txs", []) or []):
                    out.append({"txid": t.get("txid", ""),
                                "amount": float(t.get("value") or 0),
                                "time": str(t.get("time") or "")})
            except Exception:
                pass
    elif coin == "ETH":
        try:
            with _ur.urlopen(
                "https://blockscout.com/eth/mainnet/api?module=account"
                f"&action=txlist&address={addr}&sort=desc", timeout=15) as r:
                txs = _json.loads(r.read().decode()).get("result", []) or []
            for t in txs:
                if str(t.get("isError", "0")) != "0":
                    continue
                out.append({"txid": t.get("hash", ""),
                            "amount": float(t.get("value") or 0) / 1e18,
                            "time": t.get("timeStamp", "")})
        except Exception:
            pass
        if not out:
            try:
                with _ur.urlopen(
                    f"https://api.ethplorer.io/getAddressTransactions/{addr}?apiKey=freekey&limit=20",
                    timeout=15) as r:
                    txs = _json.loads(r.read().decode())
                for t in txs:
                    if not t.get("success", True):
                        continue
                    out.append({"txid": t.get("hash", ""),
                                "amount": float(t.get("value") or 0),
                                "time": str(t.get("timestamp") or "")})
            except Exception:
                pass
    elif coin == "SOL":
        try:
            with _ur.urlopen(
                f"https://public-api.solscan.io/account/transactions?account={addr}&limit=20",
                timeout=15) as r:
                txs = _json.loads(r.read().decode())
            for t in txs:
                amt = 0.0
                for p in (t.get("parsedInstruction") or []):
                    for tp in (p.get("params") or []):
                        if isinstance(tp, dict) and tp.get("destination") == addr:
                            amt += float(tp.get("amount") or 0)
                if amt > 0:
                    out.append({"txid": t.get("txHash", ""),
                                "amount": amt / 1e9,
                                "time": str(t.get("blockTime") or "")})
        except Exception:
            pass
        if not out:
            # fallback: Solana JSON-RPC via public Ankr endpoint
            try:
                req = _ur.Request(
                    "https://rpc.ankr.com/solana",
                    data=_json.dumps({
                        "jsonrpc": "2.0", "id": 1, "method": "getSignaturesForAddress",
                        "params": [addr, {"limit": 20}],
                    }).encode(),
                    headers={"Content-Type": "application/json"})
                with _ur.urlopen(req, timeout=15) as r:
                    sigs = _json.loads(r.read().decode()).get("result", []) or []
                for s in sigs:
                    req2 = _ur.Request(
                        "https://rpc.ankr.com/solana",
                        data=_json.dumps({
                            "jsonrpc": "2.0", "id": 1, "method": "getTransaction",
                            "params": [s.get("signature"), {"encoding": "jsonParsed", "maxSupportedTransactionVersion": 0}],
                        }).encode(),
                        headers={"Content-Type": "application/json"})
                    with _ur.urlopen(req2, timeout=15) as r2:
                        td = _json.loads(r2.read().decode()).get("result") or {}
                    meta = td.get("meta") or {}
                    pre = (meta.get("preBalances") or [])
                    post = (meta.get("postBalances") or [])
                    amt = 0.0
                    if len(pre) == len(post):
                        acct = (td.get("transaction", {}).get("message", {}).get("accountKeys") or [])
                        for i, ak in enumerate(acct):
                            if ak == addr and post[i] > pre[i]:
                                amt += (post[i] - pre[i]) / 1e9
                    if amt > 0:
                        out.append({"txid": s.get("signature", ""),
                                    "amount": amt,
                                    "time": str((td.get("blockTime") or 0))})
            except Exception:
                pass
    return out


def _iso_epoch(s: str) -> float:
    """ISO timestamp (order.created) -> epoch seconds. 0 on garbage."""
    try:
        return datetime.fromisoformat(s).timestamp()
    except Exception:
        return 0.0


def _tx_epoch(t) -> float:
    """Explorer tx time -> epoch seconds. Explorers return unix epoch strings
    (blockstream/mempool/sochain/blockscout/ethplorer/solscan); anything
    unparseable yields 0 and is NOT filtered out (fail-open)."""
    try:
        return float(t or 0)
    except Exception:
        return 0.0


# ── Live USD pricing (prices move — never quote a fixed coin amount) ──
_COIN_PRICE_CACHE = {"t": 0.0, "data": {}}
_COIN_IDS = {"BTC": "bitcoin", "LTC": "litecoin", "ETH": "ethereum", "SOL": "solana"}


def _fetch_prices_batch() -> dict:
    """Warm the USD price of EVERY supported coin in one pass.
    Coingecko batch → Coinbase per-coin → Kraken batch. Never raises.
    Returns {COIN: usd} for every coin that resolved."""
    import urllib.request as _ur
    import json as _json
    out = {}

    # 1. Coingecko — all coins in a single request
    try:
        _ids = ",".join(_COIN_IDS.values())
        with _ur.urlopen(
            f"https://api.coingecko.com/api/v3/simple/price?ids={_ids}&vs_currencies=usd",
            timeout=8) as r:
            _d = _json.loads(r.read().decode("utf-8", "replace"))
        for _c, _cid in _COIN_IDS.items():
            _p = float(((_d or {}).get(_cid) or {}).get("usd") or 0)
            if _p > 0:
                out[_c] = _p
    except Exception:
        pass

    # 2. Coinbase — per missing coin (very reliable, no key)
    _missing = [c for c in _COIN_IDS if c not in out]
    for _c in _missing:
        try:
            with _ur.urlopen(f"https://api.coinbase.com/v2/prices/{_c}-USD/spot", timeout=6) as r:
                _p = float((_json.loads(r.read().decode("utf-8", "replace")).get("data") or {}).get("amount") or 0)
            if _p > 0:
                out[_c] = _p
        except Exception:
            pass

    # 3. Kraken — batch for whatever is still missing
    _missing = [c for c in _COIN_IDS if c not in out]
    if _missing:
        _kmap = {"BTC": "XBTUSD", "LTC": "LTCUSD", "ETH": "ETHUSD", "SOL": "SOLUSD"}
        try:
            _pairs = ",".join(_kmap[c] for c in _missing)
            with _ur.urlopen(f"https://api.kraken.com/0/public/Ticker?pair={_pairs}", timeout=8) as r:
                _d = _json.loads(r.read().decode("utf-8", "replace"))
            _res = _d.get("result") or {}
            for _c in _missing:
                _p = float(((_res.get(_kmap[_c]) or {}).get("c") or [0])[0] or 0)
                if _p > 0:
                    out[_c] = _p
        except Exception:
            pass
    return out


def _coin_price_usd(coin: str) -> float:
    """Current coin price in USD. A miss warms ALL coins (batch + fallbacks)
    and caches 60s so the checkout tracker stays live. Returns 0.0 only when
    every source failed."""
    _c = (coin or "").upper()
    if _c not in _COIN_IDS:
        return 0.0
    now = time.time()
    if now - _COIN_PRICE_CACHE.get("t", 0) < 60:
        return float(_COIN_PRICE_CACHE.get("data", {}).get(_c, 0) or 0)
    _prices = _fetch_prices_batch()
    if _prices:
        # Full success — replace the cache.
        _COIN_PRICE_CACHE["t"] = time.time()
        _COIN_PRICE_CACHE["data"] = _prices
    elif _COIN_PRICE_CACHE.get("data"):
        # Every source failed — keep the last good prices instead of zeroing out.
        pass
    else:
        _COIN_PRICE_CACHE["t"] = time.time()
        _COIN_PRICE_CACHE["data"] = {}
    return float(_COIN_PRICE_CACHE.get("data", {}).get(_c, 0) or 0)


_EUR_CACHE = {"t": 0.0, "rate": 0.0}


def _eur_per_usd() -> float:
    """USD -> EUR conversion rate, cached 60s. Coinbase rates → static 0.92.
    Never raises."""
    now = time.time()
    if now - _EUR_CACHE.get("t", 0) < 60 and _EUR_CACHE.get("rate"):
        return float(_EUR_CACHE["rate"])
    rate = 0.0
    try:
        import urllib.request as _ur
        import json as _json
        with _ur.urlopen("https://api.coinbase.com/v2/exchange-rates?currency=USD",
                         timeout=6) as r:
            _d = _json.loads(r.read().decode("utf-8", "replace"))
            rate = float((((_d or {}).get("data") or {}).get("rates") or {}).get("EUR") or 0)
    except Exception:
        pass
    if rate > 0:
        _EUR_CACHE["t"] = time.time()
        _EUR_CACHE["rate"] = rate
        return rate
    if _EUR_CACHE.get("rate"):
        return float(_EUR_CACHE["rate"])
    return 0.92


def _tier_price_usd(tier: str) -> float:
    """USD price of a tier (from the fixed cent price — $5 / $15 / $75)."""
    return float((_sub_tiers().get(tier or "", {}) or {}).get("cents", 0)) / 100.0


# ── Plisio provider ──────────────────────────────────────────
# The panel never exposes the operator's wallet. Every order becomes a
# Plisio invoice: Plisio converts USD to coin at its own rate, hosts the
# payment page, tracks confirmations and pushes an IPN callback when the
# invoice completes. 0% underpayment — only "completed" counts.

_PLISIO_API = "https://api.plisio.net/api/v1"
_PLISIO_PAID = ("completed",)
_PLISIO_DEAD = ("expired", "cancelled", "error", "mismatch")


def _plisio_key() -> str:
    return (os.environ.get("PLISIO_API_KEY", "") or "").strip() or _settings_get("plisio_api_key")


def _plisio_request(method: str, path: str, payload=None) -> dict:
    """Talk to Plisio. Official API style (getting-started docs): HTTP GET
    only, api_key in the query string, JSON responses. Returns the response
    dict, or {"_error": ..., "_http": ...} on failure — never raises, never
    logs the key."""
    key = _plisio_key()
    if not key:
        return {"_error": "no API key configured", "_http": 0}
    import urllib.parse as _up
    import urllib.request as _ur
    import urllib.error as _ue
    import json as _json
    _flat = {k: v for k, v in payload.items() if v is not None} if isinstance(payload, dict) else {}
    _qs = _up.urlencode(_flat)
    _hdrs = {"Accept": "application/json",
             "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                           "AppleWebKit/537.36 (KHTML, like Gecko) "
                           "Chrome/126.0.0.0 Safari/537.36"}
    _meth = "GET" if str(method).upper() == "GET" else str(method).upper()
    if _meth == "GET":
        _url = _PLISIO_API + path + "?api_key=" + _up.quote(key, safe="")
        if _flat:
            _url += "&" + _qs
        _data = None
    else:
        # Plisio is GET-only, but keep POST working for anything that ever
        # accepted it: api_key in the query, params as a form body.
        _url = _PLISIO_API + path + "?api_key=" + _up.quote(key, safe="")
        _hdrs["Content-Type"] = "application/x-www-form-urlencoded"
        _data = _qs.encode()
    try:
        req = _ur.Request(_url, data=_data, method=_meth, headers=_hdrs)
        with _ur.urlopen(req, timeout=20) as r:
            return _json.loads(r.read().decode("utf-8", "replace"))
    except _ue.HTTPError as e:
        try:
            _body = _json.loads(e.read().decode("utf-8", "replace"))
        except Exception:
            _body = {}
        _d = _body.get("data") or {}
        _name = str(_d.get("name") or "") or str(_body.get("status") or "")
        _msg = str(_d.get("message") or "")[:200]
        return {"_error": (f"{_name}: {_msg}").strip() or f"HTTP {e.code}",
                "_http": e.code}
    except Exception as e:
        return {"_error": f"unreachable ({type(e).__name__})", "_http": 0}


def _plisio_create(usd: float, coin: str, oid: str, tier: str, callback: str) -> dict:
    """Create an invoice per the official docs: GET /invoices/new with
    currency (crypto code) + source_currency/source_amount (USD pricing).
    json=true on the callback_url makes Plisio POST the callback as JSON,
    which is required for non-PHP receivers to verify the signature."""
    _payload = {
        "currency": (coin or "").upper(),
        "source_currency": "USD",
        "source_amount": usd,
        "order_number": oid,
        "order_name": "VELUM " + (tier or "").upper(),
    }
    # Callback is optional for Plisio; only send it when it's a real https
    # domain (http://IP:port callbacks get rejected, and the panel polls
    # invoice status itself anyway).
    if isinstance(callback, str) and callback.startswith("https://"):
        _payload["callback_url"] = callback + "?json=true"
    resp = _plisio_request("GET", "/invoices/new", _payload)
    if not isinstance(resp, dict) or "data" not in resp:
        return resp  # carries _error / _http
    data = (resp or {}).get("data") or {}
    # Non-white-label responses omit "amount" — fall back so the checkout
    # page can always show the exact sum to send.
    if not data.get("amount"):
        data["amount"] = data.get("invoice_total_sum") or data.get("invoice_sum") or ""
    return data

def _plisio_get_invoice(txn: str) -> dict:
    """Fetch one invoice/operation by txn_id. The lookup endpoint is the
    operations LIST with a txn_id filter — /operations/{id} does not exist."""
    resp = _plisio_request("GET", "/operations", {"txn_id": str(txn)})
    data = (resp or {}).get("data")
    if isinstance(data, list):
        for _rec in data:
            if isinstance(_rec, dict) and str(_rec.get("txn_id") or "") == str(txn):
                return _rec
        return data[0] if data and isinstance(data[0], dict) else {}
    return data if isinstance(data, dict) else {}


def _php_serialize(obj) -> str:
    """Minimal PHP serialize() for flat POST arrays (all values strings),
    matching what Plisio signs in form-encoded callbacks."""
    if isinstance(obj, dict):
        parts = ["a:%d:{" % len(obj)]
        for k in obj:
            parts.append(_php_serialize(str(k)))
            parts.append(_php_serialize(obj[k]))
        parts.append("}")
        return "".join(parts)
    if isinstance(obj, str):
        return 's:%d:"%s";' % (len(obj.encode("utf-8")), obj)
    if obj is None:
        return "N;"
    if isinstance(obj, bool):
        return "b:%d;" % (1 if obj else 0)
    if isinstance(obj, int):
        return "i:%d;" % obj
    return _php_serialize(str(obj))


def _plisio_verify_callback(raw_body: str) -> bool:
    """Verify a Plisio callback. JSON body (callback_url carried json=true):
    HMAC-SHA1 over the compact JSON minus verify_hash — matches Plisio's
    Node reference. Form-encoded body (PHP default): HMAC-SHA1 over the
    PHP-serialized, key-sorted POST minus verify_hash — matches the PHP
    reference. Returns True only when the hash matches."""
    try:
        import json as _json
        _raw = (raw_body or "").strip()
        if not _raw:
            return False
        _key = _plisio_key().encode("utf-8")
        if _raw.startswith("{"):
            _obj = _json.loads(_raw)
            if not isinstance(_obj, dict):
                return False
            _hash = _obj.get("verify_hash")
            if not isinstance(_hash, str) or not _hash:
                return False
            _obj.pop("verify_hash", None)
            _post = _json.dumps(_obj, separators=(",", ":")).encode("utf-8")
            _digest = hmac.new(_key, _post, hashlib.sha1).hexdigest()
            return hmac.compare_digest(_digest, _hash)
        # form-encoded fallback (PHP signing style)
        from urllib.parse import parse_qsl
        import html as _html
        post = {}
        for _k, _v in parse_qsl(_raw, keep_blank_values=True):
            post[_k] = _v
        _hash = post.get("verify_hash")
        if not _hash:
            return False
        post.pop("verify_hash", None)
        if "expire_utc" in post:
            post["expire_utc"] = str(post["expire_utc"])
        if "tx_urls" in post:
            post["tx_urls"] = _html.unescape(post["tx_urls"])
        _ser = _php_serialize({k: post[k] for k in sorted(post)})
        _digest = hmac.new(_key, _ser.encode("utf-8"), hashlib.sha1).hexdigest()
        return hmac.compare_digest(_digest, _hash)
    except Exception:
        return False


def _plisio_parse_callback_body(raw_body: str) -> dict:
    """Callback payload as a dict — JSON or form-encoded."""
    import json as _json
    _raw = (raw_body or "").strip()
    if _raw.startswith("{"):
        try:
            _d = _json.loads(_raw)
            return _d if isinstance(_d, dict) else {}
        except Exception:
            return {}
    from urllib.parse import parse_qsl
    return {k: v for k, v in parse_qsl(_raw, keep_blank_values=True)}


def _plisio_cancel_invoice(txn: str) -> dict:
    """Best-effort provider-side invoice cancellation. Plisio's public API
    has no cancel endpoint (invoices auto-expire on their TTL), so this
    attempts the canonical path and reports what the provider said.
    Never raises."""
    resp = _plisio_request("GET", "/invoices/cancel", {"txn_id": str(txn)})
    if isinstance(resp, dict) and "_error" in resp:
        return {"cancelled": False, "reason": str(resp.get("_error"))}
    return {"cancelled": True, "reason": ""}


def _check_order(oid: str) -> bool:
    """Verify a pending order. Plisio's invoice status is the only truth:
    "completed" = exact amount received (0% underpayment), anything dead
    expires the order."""
    row = _q("SELECT * FROM orders WHERE id = ?", (oid,), fetch=True)
    if not row or row[0]["status"] != "pending":
        return False
    o = dict(row[0])
    pid = o.get("payment_id") or ""
    if pid:
        inv = _plisio_get_invoice(pid)
        st = str(inv.get("status") or "").lower()
        if st in _PLISIO_PAID:
            # Atomic claim: only the worker whose UPDATE wins mints, so two
            # watchers (gunicorn workers) can never double-issue the key.
            conn = _db()
            cur = conn.cursor()
            cur.execute(_ph("UPDATE orders SET status = 'minting' "
                            "WHERE id = ? AND status = 'pending'"), (oid,))
            claimed = cur.rowcount
            conn.commit()
            if not claimed:
                return False
            _key = _license_mint(o["tier"], o["username"], o["coin"], pid)
            _q("UPDATE orders SET status = 'paid', paid_at = ?, license_key = ? WHERE id = ?",
               (_now(), _key, oid))
            print(f"[PAY] order {oid} -> paid via {o.get('coin', '?')} (txn {pid[:16]}), "
                  f"key minted for {o['username']}", flush=True)
            return True
        if st in _PLISIO_DEAD:
            _q("UPDATE orders SET status = 'expired' WHERE id = ?", (oid,))
        return False
    # Legacy order without a provider invoice — just let it expire.
    cutoff = (datetime.now(timezone.utc) - timedelta(hours=6)).isoformat(timespec="seconds")
    _q("UPDATE orders SET status = 'expired' WHERE id = ? AND created < ?", (oid, cutoff))
    return False


def _tick_all():
    rows = _q("SELECT id FROM orders WHERE status = 'pending' ORDER BY created LIMIT 50", fetch=True) or []
    paid = 0
    for r in rows:
        try:
            if _check_order(r["id"]):
                paid += 1
        except Exception:
            pass
    return paid


# Payment watcher — starts in EVERY process, gunicorn workers included, so
# paid orders flip themselves with nobody watching a browser. Each tick is
# idempotent and mints atomically (see _check_order).
def _payment_watcher():
    while True:
        time.sleep(15)
        try:
            _tick_all()
        except Exception:
            pass


threading.Thread(target=_payment_watcher, daemon=True).start()


