@app.post("/api/panel/orders")
def panel_order_create():
    role, uname = _auth()
    if role is None:
        return jsonify({"error": "unauthorized"}), 403
    d = request.get_json(force=True, silent=True) or {}
    tier = str(d.get("tier") or "").strip().lower()
    coin = str(d.get("coin") or "").strip().upper()
    if tier not in _sub_tiers() or coin not in ("BTC", "LTC", "ETH", "SOL"):
        return jsonify({"error": f"bad tier or coin (tier={tier!r}, coin={coin!r})"}), 400
    if not _plisio_key():
        return jsonify({"error": "payments aren't configured yet"}), 400
    # The provider converts USD to coin at its own live rate and hosts a
    # payment page for this order. Our wallet address is never exposed.
    usd = _tier_price_usd(tier)
    oid = uuid.uuid4().hex[:12]
    callback = request.host_url.rstrip("/") + "/api/ipn/plisio"
    inv = _plisio_create(usd, coin, oid, tier, callback)
    if "_error" in inv:
        return jsonify({"error": "payment provider: " + str(inv.get("_error"))}), 502
    txn = str(inv.get("txn_id") or "")
    if not txn:
        return jsonify({"error": "payment provider returned no invoice — try again in a minute"}), 502
    pay_amount = str(inv.get("amount") or "")
    pay_url = str(inv.get("invoice_url") or "")
    _q("INSERT INTO orders (id, username, tier, coin, amount, address, status, created, paid_at, license_key, payment_id) "
       "VALUES (?,?,?,?,?,?,?,?,NULL,NULL,?)",
       (oid, uname, tier, coin, pay_amount, pay_url, "pending", _now(), txn))
    return jsonify({"ok": True, "id": oid, "coin": coin, "address": pay_url,
                    "amount": pay_amount, "usd": round(usd, 2), "tier": tier,
                    "payment_id": txn})


# ── Plisio IPN callback ──────────────────────────────────────
# Plisio POSTs the operation here when an invoice changes state. The payload
# is verified with the official HMAC-SHA1 signature before it is trusted,
# then the order is re-verified against Plisio's API — the callback itself
# never mints anything on its word alone.

@app.route("/api/ipn/plisio", methods=["GET", "POST"])
def plisio_ipn():
    if request.method == "GET":
        # Browsers (and people testing the callback URL) hit this with GET —
        # answer instead of 404ing so the endpoint doesn't look broken.
        return jsonify({"ok": True, "note": "Plisio IPN endpoint — the provider POSTs here"})
    raw = request.get_data(as_text=True) or ""
    if not _plisio_verify_callback(raw):
        print("[IPN] callback rejected — bad or missing signature", flush=True)
        return jsonify({"ok": False, "error": "bad signature"}), 403
    d = _plisio_parse_callback_body(raw)
    txn = str(d.get("txn_id") or d.get("invoice_id") or "")
    status = str(d.get("status") or "").lower()
    order_number = str(d.get("order_number") or "")
    print(f"[IPN] received: txn={txn[:16]} status={status} order_number={order_number}", flush=True)
    if not txn:
        print("[IPN] no txn_id in callback — ignored", flush=True)
        return jsonify({"ok": False, "error": "missing txn_id"}), 400
    rows = _q("SELECT id FROM orders WHERE payment_id = ?", (txn,), fetch=True)
    if not rows:
        # Also match by our internal order id when Plisio sends order_number.
        if order_number:
            rows = _q("SELECT id FROM orders WHERE id = ?", (order_number,), fetch=True)
    if not rows:
        print(f"[IPN] no order matches txn={txn[:16]} order_number={order_number} — ignored", flush=True)
        return jsonify({"ok": False, "error": "unknown order"}), 404
    oid = rows[0]["id"]
    try:
        # Re-verify with the provider API before touching anything: the
        # signed callback only triggers the check, the API is the truth.
        paid = _check_order(oid)
        if not paid:
            _ost = (_q("SELECT status FROM orders WHERE id = ?", (oid,), fetch=True) or [{}])
            if _ost and dict(_ost[0]).get("status") == "cancelled":
                print(f"[IPN] order {oid} is cancelled — callback verified, no delivery", flush=True)
        print(f"[IPN] order {oid} txn={txn[:16]}: processed, newly_paid={paid}", flush=True)
    except Exception as _e:
        print(f"[IPN] order {oid} processing failed: {_e!r}", flush=True)
    return jsonify({"ok": True})


