@app.delete("/api/panel/orders/<oid>")
def panel_order_cancel(oid):
    """Cancel a pending order. Server-side only: checks the provider first
    (a paid invoice cannot be cancelled), attempts to cancel the Plisio
    invoice, then marks the order cancelled locally. The row is kept so a
    delayed callback can match it — the status guard in _check_order then
    refuses delivery, so a cancelled order can never be fulfilled."""
    role, uname = _auth()
    if role is None:
        return jsonify({"error": "unauthorized"}), 403
    rows = _q("SELECT id, username, status, payment_id FROM orders WHERE id = ?", (oid,), fetch=True)
    if not rows:
        return jsonify({"error": "not found"}), 404
    o = dict(rows[0])
    if role != "admin" and o["username"] != uname:
        return jsonify({"error": "unauthorized"}), 403
    if o["status"] != "pending":
        return jsonify({"error": "only pending orders can be cancelled"}), 400
    txn = str(o.get("payment_id") or "")
    prov = {"cancelled": False, "reason": ""}
    if txn:
        # A legitimately completed payment wins over a cancel click.
        inv = _plisio_get_invoice(txn)
        if str(inv.get("status") or "").lower() in _PLISIO_PAID:
            print(f"[CANCEL] order {oid} txn={txn[:16]}: already paid at provider — cancel refused", flush=True)
            return jsonify({"error": "already paid"}), 409
        prov = _plisio_cancel_invoice(txn)
        if prov.get("cancelled"):
            print(f"[CANCEL] order {oid} txn={txn[:16]}: provider invoice cancelled", flush=True)
        else:
            print(f"[CANCEL] order {oid} txn={txn[:16]}: provider cancel not applied — {prov.get('reason')}", flush=True)
    else:
        print(f"[CANCEL] order {oid}: no payment_id on record — local cancel only", flush=True)
    _q("UPDATE orders SET status = 'cancelled', cancelled_at = ?, address = NULL WHERE id = ?",
       (_now(), oid))
    print(f"[CANCEL] order {oid} -> cancelled locally, invoice link cleared", flush=True)
    return jsonify({"ok": True, "cancelled": True,
                    "provider_cancelled": bool(prov.get("cancelled")),
                    "provider_note": prov.get("reason", "")})


