@app.post("/api/trial/request")
def trial_request():
    """Public free-trial mint — ONE trial per IP, ever. VPN/proxy/Tor sources
    are refused outright (403 + vpn flag), the IP is burned on first claim so
    a new account cannot farm a second key, and trial_daily_cap (default 100)
    stops bulk abuse."""
    if not _sub_tiers().get("trial"):
        return jsonify({"ok": False, "error": "trials are disabled"}), 400
    d = request.get_json(force=True, silent=True) or {}
    ip = _client_ip() or "anon"
    ip_h = hashlib.sha256(("velum-trial|" + ip).encode()).hexdigest()[:40]
    ip_masked = ".".join(ip.split(".")[:2]) + ".*.*" if ip.count(".") >= 2 else (ip[:4] + "****")
    # ── VPN / proxy / Tor wall — refused before anything else ──
    if _is_proxy_ip(ip):
        try:
            _q("INSERT INTO trial_vpn_attempts (ip_hash, ip_masked, ts) "
               "VALUES (?,?,?)", (ip_h, ip_masked, _now()))
        except Exception:
            pass
        print(f"[TRIAL] VPN/proxy claim refused: {ip_masked}", flush=True)
        return jsonify({"ok": False, "vpn": True,
                        "error": "VPN / PROXY DETECTED — YOU CANNOT CONNECT WITH A VPN"}), 403
    # Identity: a valid JWT wins; anonymous callers are bound to their IP.
    # (The body username is ignored unless the caller is authenticated, so
    # nobody can burn another account's trial by name.)
    uname = ""
    try:
        _role, _tok_user = _auth()
        if _role:
            uname = str(_tok_user or "").strip()[:40]
    except Exception:
        uname = ""
    owner = uname or ("trial-" + ip_h[:12])
    # ── one trial per IP, FOREVER — no redo, no new-account workaround ──
    if _q("SELECT 1 FROM trial_claims WHERE ip_hash = ?", (ip_h,), fetch=True):
        return jsonify({"ok": False, "dup": True,
                        "error": "TRIAL ALREADY CLAIMED FROM THIS IP — one trial per device/network"}), 409
    # ── one trial per account, forever ──
    if uname and _q("SELECT 1 FROM licenses WHERE owner = ? AND tier = 'trial'",
                    (uname,), fetch=True):
        return jsonify({"ok": False, "dup": True,
                        "error": "TRIAL ALREADY CLAIMED BY THIS ACCOUNT"}), 409
    # ── no free ride on top of an active key ──
    if _license_state(owner).get("has"):
        return jsonify({"ok": False, "error": "you already have an active key",
                        "license": _license_state(owner)}), 409
    try:
        _cap = int(_settings_get("trial_daily_cap") or 0) or 100
    except Exception:
        _cap = 100
    _day0 = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    _cnt = (_q("SELECT COUNT(*) AS c FROM trial_claims WHERE created >= ?",
               (_day0,), fetch=True) or [{}])[0].get("c") or 0
    if int(_cnt) >= _cap:
        return jsonify({"ok": False, "error": "trial limit reached today — try tomorrow"}), 429
    key = _license_mint("trial", owner, coin="trial")
    try:
        _q("INSERT INTO trial_claims (ip_hash, ip_masked, owner, key, created) "
           "VALUES (?,?,?,?,?)", (ip_h, ip_masked, owner, key, _now()))
    except Exception:
        pass
    return jsonify({"ok": True, "key": key, "tier": "trial",
                    "days_left": 3,
                    "expires_at": _license_expiry("trial"),
                    "watermark": "VELUM-TRIAL " + key[:13],
                    "one_time": True})


