@app.post("/api/admin/command")
def admin_command():
    role, uname = _auth()
    if role is None:
        return jsonify({"error": "unauthorized"}), 403
    if role == "user" and _jwt_stale():
        return jsonify({"error": "Your session expired — sign in again."}), 401
    d = request.get_json(force=True, silent=True) or {}
    ctype = str(d.get("type") or "").lower().strip()
    if ctype not in ("info", "miner_stop", "miner_start", "sleep", "diag", "shutdown", "wake_arm"):
        return jsonify({"error": "unknown command type"}), 400
    bid = str(d.get("bot_id") or "").strip() or None
    arg = str(d.get("arg") or "")[:512]
    cid = uuid.uuid4().hex
    if role == "user":
        targets = []
        if bid:
            if not _q("SELECT 1 FROM bots WHERE id = ? AND key = ?", (bid, _user_api_key(uname)), fetch=True):
                return jsonify({"error": "bot not found"}), 404
            targets = [bid]
        else:
            targets = _user_bot_ids(uname)
            if not targets:
                return jsonify({"error": "no bots registered yet"}), 404
        for t in targets:
            _q("INSERT INTO commands (id, bot_id, type, arg, status, result, created) "
               "VALUES (?,?,?,?,?,?,?)",
               (uuid.uuid4().hex, t, ctype, arg, "pending", "", _now()))
        return jsonify({"ok": True, "id": cid, "queued": len(targets)})
    if bid and not (_q("SELECT id FROM bots WHERE id = ?", (bid,), fetch=True)):
        return jsonify({"error": "bot not found"}), 404
    _q("INSERT INTO commands (id, bot_id, type, arg, status, result, created) "
       "VALUES (?,?,?,?,?,?,?)",
       (cid, bid, ctype, str(d.get("arg") or "")[:512], "pending", "", _now()))
    return jsonify({"ok": True, "id": cid})


