# ── Fleet overview (24h aggregate hashrate series + per-algo breakdown) ──

@app.get("/api/panel/overview")
def panel_overview():
    role, uname = _auth()
    if role is None:
        return jsonify({"error": "unauthorized"}), 403
    bots = [_row(b) for b in (_q("SELECT * FROM bots", fetch=True) or [])]
    if role == "user":
        uk = _user_api_key(uname)
        bots = [b for b in bots if (b.get("key") or "") == uk]
    cutoff = (datetime.now(timezone.utc) - timedelta(hours=24)).isoformat(timespec="seconds")
    if _PG:
        bucket = "to_char(ts::timestamp, 'YYYY-MM-DD HH24:MI')"
    else:
        bucket = "strftime('%Y-%m-%d %H:%M', ts)"
    rows = _q(f"SELECT {bucket} AS b, SUM(hashrate) AS h FROM hashrate_history "
              f"WHERE ts >= ? GROUP BY b ORDER BY b", (cutoff,), fetch=True) or []
    series = [{"t": r["b"], "h": round(float(r["h"] or 0), 2)} for r in rows]
    algos = {}
    for b in bots:
        a = (b.get("miner_coin") or b.get("miner_algo") or "?").lower() or "?"
        algos.setdefault(a, {"hashrate": 0.0, "bots": 0})
        algos[a]["hashrate"] += float(b.get("hashrate") or 0)
        algos[a]["bots"] += 1
    top = sorted(bots, key=lambda b: float(b.get("hashrate") or 0), reverse=True)[:5]
    return jsonify({
        "series": series,
        "algos": [{"algo": k, "hashrate": round(v["hashrate"], 2), "bots": v["bots"]}
                  for k, v in sorted(algos.items(), key=lambda kv: -kv[1]["hashrate"])],
        "top": [{"hostname": b.get("hostname"), "hashrate": float(b.get("hashrate") or 0)}
                for b in top],
    })


