@app.get("/api/admin/users")
def admin_users():
    role, _uname = _auth()
    if role != "admin":
        return jsonify({"error": "unauthorized"}), 403
    users = _q("SELECT username, api_key, created, auth_version, balance, last_login, last_ip "
               "FROM users ORDER BY created DESC", fetch=True) or []
    users = [_row(u) for u in users]
    bots = _q("SELECT id, key, last_seen, hashrate FROM bots", fetch=True) or []
    pending_rows = _q("SELECT bot_id FROM commands WHERE status = 'pending'", fetch=True) or []
    pending_by_bot = {}
    for r in pending_rows:
        if r["bot_id"]:
            pending_by_bot[r["bot_id"]] = pending_by_bot.get(r["bot_id"], 0) + 1
    key_active = {r["key"]: bool(r["active"]) for r in (_q("SELECT key, active FROM api_keys", fetch=True) or [])}
    cutoff = (datetime.now(timezone.utc) - timedelta(seconds=_ui_settings()["online_window_secs"])).isoformat(timespec="seconds")
    out = []
    for u in users:
        ub = [b for b in bots if b["key"] == u["api_key"]]
        online = [b for b in ub if (b["last_seen"] or "") >= cutoff]
        last = max((b["last_seen"] for b in ub if b["last_seen"]), default=None)
        out.append({
            "username": u["username"],
            "api_key": u["api_key"],
            "created": u["created"],
            "auth_version": int(u["auth_version"] or 0),
            "balance": round(float(u["balance"] or 0), 2),
            "last_login": u["last_login"],
            "last_ip": u.get("last_ip") or "",
            "key_active": key_active.get(u["api_key"], False),
            "total_bots": len(ub),
            "online": len(online),
            "hashrate": round(sum(float(b["hashrate"] or 0) for b in online), 2),
            "pending": sum(pending_by_bot.get(b["id"], 0) for b in ub),
            "last_active": last,
        })
    return jsonify({"users": out})


@app.post("/api/admin/users/<username>/toggle")
def admin_user_toggle(username):
    """BAN: revoke the user's builder key + bump auth_version (their JWTs die
    on writes, bots stop checking in). UNBAN: restore the key â€” re-creating
    the key row if it was ever deleted â€” WITHOUT bumping the version again,
    so a user who logs back in is fully functional."""
    role, _uname = _auth()
    if role != "admin":
        return jsonify({"error": "unauthorized"}), 403
    rows = _q("SELECT api_key, last_ip FROM users WHERE username = ?", (username,), fetch=True)
    if not rows:
        return jsonify({"error": "user not found"}), 404
    uk = rows[0]["api_key"]
    krows = _q("SELECT active FROM api_keys WHERE key = ?", (uk,), fetch=True)
    active = bool(krows and krows[0]["active"])
    if active:
        _q("UPDATE api_keys SET active = 0 WHERE key = ?", (uk,))
        _q("UPDATE users SET auth_version = auth_version + 1 WHERE username = ?", (username,))
        # Hard IP ban too: every IP this user last logged in from gets walled.
        _uip = str(rows[0].get("last_ip") or "").strip()
        if _uip:
            _q("INSERT INTO ip_bans (ip, reason, user_id, created) "
               "SELECT ?,?,?,? WHERE NOT EXISTS (SELECT 1 FROM ip_bans WHERE ip = ?)",
               (_uip, f"banned user: {username}", username, _now(), _uip))
        new_active = False
    else:
        if krows:
            _q("UPDATE api_keys SET active = 1 WHERE key = ?", (uk,))
        else:
            _q("INSERT INTO api_keys (key, label, created, active) VALUES (?,?,?,1)",
               (uk, username, _now()))
        # Unban: lift the IP wall for this user's ban record (manual bans stay).
        _q("DELETE FROM ip_bans WHERE user_id = ?", (username,))
        new_active = True
    return jsonify({"ok": True, "active": new_active})




